mapper.select:
SELECT ${sqlMap.column.toSql()}
FROM ${sqlMap.table.toSql()}

    ${sqlMap.where.toSql()}


        AND (${sqlMap.where.sqlSegment})


        AND a.employee_id = #{employeeId}


        AND a.employee_name LIKE concat('%', #{employeeName}, '%')


        AND DATE(a.attendance_date) = DATE(#{attendanceDate})


        AND DATE(a.attendance_date) BETWEEN DATE(#{beginAttendanceDate}) AND DATE(#{endAttendanceDate})


        AND a.work_time_range LIKE concat('%', #{workTimeRange}, '%')


ORDER BY ${sqlMap.order.toSql()}

SELECT a.id AS "id", a.employee_id AS "employeeId", a.employee_name AS "employeeName", a.attendance_date AS "attendanceDate", a.work_time_range AS "workTimeRange", a.clock_in_time AS "clockInTime", a.clock_out_time AS "clockOutTime", a.scheduled_hours AS "scheduledHours", a.actual_hours AS "actualHours", a.idle_hours AS "idleHours", a.daily_efficiency AS "dailyEfficiency", a.daily_achievement_rate AS "dailyAchievementRate", a.status AS "status", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks AS "remarks" FROM swm_daily_attendance a
a.employee_id = #{employeeId} AND YEAR(a.attendance_date) = #{year} AND MONTH(a.attendance_date) = #{month}
ORDER BY a.attendance_date ASC

SELECT a.id AS "id", a.employee_id AS "employeeId", a.employee_name AS "employeeName", a.attendance_date AS "attendanceDate", a.work_time_range AS "workTimeRange", a.clock_in_time AS "clockInTime", a.clock_out_time AS "clockOutTime", a.scheduled_hours AS "scheduledHours", a.actual_hours AS "actualHours", a.idle_hours AS "idleHours", a.daily_efficiency AS "dailyEfficiency", a.daily_achievement_rate AS "dailyAchievementRate", a.status AS "status", a.create_by AS "createBy", a.create_date AS "createDate", a.update_by AS "updateBy", a.update_date AS "updateDate", a.remarks AS "remarks" FROM swm_daily_attendance a
a.employee_name = #{employeeName} AND YEAR(a.attendance_date) = #{year} AND MONTH(a.attendance_date) = #{month}
ORDER BY a.attendance_date ASC

SELECT a.id, a.employee_id, a.employee_name, a.attendance_date, a.work_time_range, a.clock_in_time, a.clock_out_time, a.scheduled_hours, a.actual_hours, a.idle_hours, a.daily_efficiency, a.daily_achievement_rate, a.attendance_normal, a.current_position, a.create_by, a.create_date, a.update_by, a.update_date, a.remarks, a.status FROM swm_daily_attendance a WHERE a.status = '0'
AND a.employee_id = #{employeeId}
AND DATE_FORMAT(a.attendance_date, '%Y-%m') = #{month} ORDER BY a.attendance_date DESC, a.update_date DESC
